insert into nodes (node_type, slug, title, summary, status, meta_title, meta_description, legacy_slugs, published_at) values ('article', 'malediven-urlaub', 'Malediven Urlaub', 'Alles, was ein Besucher von den Malediven braucht, ist hier mit Live-Chat. Hier finden Sie Informationen, die Sie benotigen, Aktivitaten oder ein Hotel zum Verweilen', 'published', 'Malediven Urlaub | Maldives Travel Guide | MTG', 'Alles, was ein Besucher von den Malediven braucht, ist hier mit Live-Chat. Hier finden Sie Informationen, die Sie benotigen, Aktivitaten oder ein Hotel zum Verweilen', ARRAY['/articles/malediven-urlaub.html']::text[], now()) on conflict (node_type, slug) do nothing;
insert into articles (id, body, reading_time_minutes) select id, '<h3>13.Die Gemeinschaft</h3><p>Mit 515.696 Einwohnern auf einer Flache von 298 Quadratkilometern sind die Malediven das kleinste Land in Asien und geografisch eines der am starksten zerstreuten Lander der Welt. Das Land ist in 26 Gebiete (Atolle) unterteilt. Von den insgesamt 1200 Inseln leben Menschen auf 200 Inseln. Die durchschnittliche Bevolkerung der Inseln betragt 2000 Menschen. Einige Inseln sind mit 400 Menschen bewohnt, aber jede Insel ist durch das Meer getrennt, weshalb das Reisen zwischen den Inseln fur uns (Einheimische) und Besucher immer eine Herausforderung war.</p><h4>Kampfe des Landes</h4><p>Die Malediven wurde auf der Top - 20 armsten Landern der Welt in den 1980er Jahren aufgefuhrt Bericht der Weltbank. In der Vergangenheit war das Land hauptsachlich auf kostenlose Spenden angewiesen. Nachdem der Tourismus 1972 langsam begann, begann das Land zu wachsen und heute steht das Land auf den Beinen, aber die Streuung des Landes macht es dennoch schwierig, das Land zu regieren.</p><p>Transportation</p><p>Wasser trinken</p><p>Bildung</p><p>Medizinisch</p><h4>Das niedrigste Land der Welt</h4><p>Keine der Koralleninseln der Malediven ist hoher als 1,8 Meter uber dem Meeresspiegel und damit das niedrigste Land der Welt. Es besteht die Gefahr, in den Ozean einzutauchen, bei Flut in der Hauptstadt erreicht der Meeresspiegel 7 Zoll.</p><p>Bodenerosion</p><p>Die Malediven befinden sich im Zentrum der Welt, getrennt durch einen riesigen Ozean, und sind auch einer starken Meeresstromung ausgesetzt. Dies ist vermutlich einer der Grunde fur die Bodenerosion. Dies wird zu einer groen Bedrohung fur viele Inseln und ihre Volker. Um diese kleinen Inseln zu schutzen, werden Steinkasernen benotigt.</p><h4>Ocean Day</h4><p>Obwohl die gesamte Wirtschaft der Malediven vom Tourismus abhangt, ist Nachlassigkeit ein Teil der Gemeinschaft. Viele Kunststoffe werden im Malediven Ozean gegrundet. Auf den Malediven wird jedes Jahr am 8. Juni der Weltmeertag gefeiert, und einige der Organisatoren des Zivildienstes organisieren die Reinigung unserer Hausriffe und entfernen Plastik aus dem Meer.</p><h4>Das Leben eines Maledivers - eine Erfahrung jenseits Ihrer Vorstellungskraft -</h4><p>Die Malediven sind facettenreich. Die Kultur, Traditionen und Brauche des Landes werden hauptsachlich von srilankischen, malaysischen, arabischen, indischen, persischen, indonesischen und sogar afrikanischen Einflussen beeinflusst. Eine fabelhafte kulturelle Mischung, die den ganzen Reichtum der Malediven ausmacht.</p>', 2 from nodes where node_type = 'article' and slug = 'malediven-urlaub' on conflict (id) do nothing;
